import java.sql.*;

public class UserAuth {
    public boolean authenticateUser(String username, String password) {
        // secure: Using PreparedStatement prevents SQL injection attacks
        // User input is passed as parameterized values, not concatenated into the query
        // The JDBC driver properly escapes all input, neutralizing injection attempts
        String query = "SELECT * FROM users WHERE username = ? AND password = ?";

        try {
            Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "user", "pass");
            PreparedStatement pstmt = conn.prepareStatement(query);
            pstmt.setString(1, username);
            pstmt.setString(2, password);
            ResultSet rs = pstmt.executeQuery();

            return rs.next();
        } catch (SQLException e) {
            e.printStackTrace();
            return false;
        }
    }
}
