    "equipment": "Assessment materials, technology for data collection, and secure storage systems",
    "participant_compensation": "Remuneration for time and travel expenses for all assessment sessions",
    "dissemination": "Publication fees, conference travel, and public-facing material development",
    "indirect_costs": "Institutional overhead and administrative support"
  },

  "limitations_and_mitigations": {
    "limitation_one": {
      "issue": "Self-reported environmental exposure data may be subject to recall bias",
      "mitigation": "Triangulation with objective measures including technology usage logs and school schedule documentation"
